let currentLang='ar';
let currentUser=null;
let currentBooking={dest:'', price:0};
let userBookings = [];

window.addEventListener('DOMContentLoaded', () => {
  const savedUser = localStorage.getItem('mm_current_user');
  if(savedUser){
    currentUser = JSON.parse(savedUser);
    updateUserUI();
  }
  const savedBookings = localStorage.getItem('mm_user_bookings');
  if(savedBookings){
    userBookings = JSON.parse(savedBookings);
  }
});

function setLanguage(lang){
  currentLang=lang;
  const t=translations[lang];
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  document.body.classList.toggle('en',lang==='en');
  document.getElementById('langToggle').textContent=lang==='ar'?'English':'العربية';
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key=el.dataset.i18n;
    if(t[key]!==undefined)el.innerHTML=t[key];
  });
  document.getElementById('menuBtn').setAttribute('aria-label',lang==='ar'?'فتح القائمة':'Open menu');
  document.getElementById('name').placeholder=lang==='ar'?'اسمك':'Your name';
  document.getElementById('message').placeholder=lang==='ar'?'الوجهة، عدد المسافرين، والميزانية التقريبية...':'Destination, number of travelers, and approximate budget...';
  document.title=lang==='ar'?'M&M Tours And Travel | اكتشف العالم':'M&M Tours And Travel | Discover the world';
}

function updateDynamicPrices(selectedDateStr){
  let multiplier = 1.0;
  if(selectedDateStr){
    const d = new Date(selectedDateStr);
    const month = d.getMonth() + 1;
    if([6, 7, 8, 12].includes(month)){ multiplier = 1.25; }
    else if([3, 4, 10, 11].includes(month)){ multiplier = 1.10; }
    else { multiplier = 0.95; }
  }

  document.querySelectorAll('.destination .dest-foot span[data-base]').forEach(span=>{
    const base = parseFloat(span.dataset.base);
    const updated = Math.round(base * multiplier);
    span.textContent = currentLang === 'ar' ? `يبدأ من ${updated.toLocaleString()} جنيه` : `From EGP ${updated.toLocaleString()}`;
  });

  document.querySelectorAll('.packages .price strong[data-base]').forEach(strong=>{
    const base = parseFloat(strong.dataset.base);
    const updated = Math.round(base * multiplier);
    strong.textContent = currentLang === 'ar' ? `يبدأ من ${updated.toLocaleString()} جنيه` : `From EGP ${updated.toLocaleString()}`;
  });
}

function showCountryHotels(countryId, btnElement) {
  document.querySelectorAll('.country-hotel-list').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
  
  const target = document.getElementById(countryId);
  if(target) target.style.display = 'block';
  if(btnElement) btnElement.classList.add('active');
}

['input', 'change'].forEach(evt => {
  const globalDateInput = document.getElementById('globalDateFilter');
  const travelDateInput = document.getElementById('travelDate');
  const contactDateInput = document.getElementById('date');

  if(globalDateInput){
    globalDateInput.addEventListener(evt, (e)=>{
      updateDynamicPrices(e.target.value);
      if(travelDateInput) travelDateInput.value = e.target.value;
      if(contactDateInput) contactDateInput.value = e.target.value;
    });
  }
  if(travelDateInput){
    travelDateInput.addEventListener(evt, (e)=>{
      if(globalDateInput) globalDateInput.value = e.target.value;
      updateDynamicPrices(e.target.value);
    });
  }
  if(contactDateInput){
    contactDateInput.addEventListener(evt, (e)=>{
      if(globalDateInput) globalDateInput.value = e.target.value;
      updateDynamicPrices(e.target.value);
    });
  }
});

function toast(msg){
  const el=document.getElementById('toast');
  el.textContent=msg;
  el.classList.add('show');
  window.setTimeout(()=>el.classList.remove('show'),4000);
}

const authModal=document.getElementById('authModal');
const checkoutModal=document.getElementById('checkoutModal');
const bookingsModal=document.getElementById('bookingsModal');

document.getElementById('loginBtn').addEventListener('click',()=>openAuth('login'));
document.getElementById('heroAccountBtn').addEventListener('click',()=>openAuth('register'));
document.getElementById('ctaRegisterBtn').addEventListener('click',()=>openAuth('register'));
document.getElementById('closeAuthModal').addEventListener('click',()=>authModal.classList.remove('open'));
document.getElementById('closeCheckoutModal').addEventListener('click',()=>checkoutModal.classList.remove('open'));
document.getElementById('closeBookingsModal').addEventListener('click',()=>bookingsModal.classList.remove('open'));
document.getElementById('myBookingsTrigger').addEventListener('click',()=>openMyBookings());

document.getElementById('switchToRegister').addEventListener('click',(e)=>{
  e.preventDefault();
  document.getElementById('loginView').style.display='none';
  document.getElementById('registerView').style.display='block';
});
document.getElementById('switchToLogin').addEventListener('click',(e)=>{
  e.preventDefault();
  document.getElementById('registerView').style.display='none';
  document.getElementById('loginView').style.display='block';
});

function openAuth(view){
  authModal.classList.add('open');
  if(view==='login'){
    document.getElementById('loginView').style.display='block';
    document.getElementById('registerView').style.display='none';
  } else {
    document.getElementById('registerView').style.display='block';
    document.getElementById('loginView').style.display='none';
  }
}

document.getElementById('loginForm').addEventListener('submit',(e)=>{
  e.preventDefault();
  const email=document.getElementById('loginEmail').value;
  currentUser={name: email.split('@')[0], email: email};
  localStorage.setItem('mm_current_user', JSON.stringify(currentUser));
  authModal.classList.remove('open');
  updateUserUI();
  toast(translations[currentLang].loginSuccess);
});

document.getElementById('registerForm').addEventListener('submit',(e)=>{
  e.preventDefault();
  const name=document.getElementById('regName').value;
  const email=document.getElementById('regEmail').value;
  currentUser={name: name, email: email};
  localStorage.setItem('mm_current_user', JSON.stringify(currentUser));
  authModal.classList.remove('open');
  updateUserUI();
  toast(translations[currentLang].registerSuccess);
});

document.getElementById('logoutBtn').addEventListener('click',()=>{
  currentUser=null;
  localStorage.removeItem('mm_current_user');
  updateUserUI();
  toast(translations[currentLang].logoutSuccess);
});

function updateUserUI(){
  if(currentUser){
    document.getElementById('authActions').style.display='none';
    document.getElementById('userProfileArea').style.display='flex';
    document.getElementById('userNameDisplay').textContent=`👤 ${currentUser.name}`;
  } else {
    document.getElementById('authActions').style.display='flex';
    document.getElementById('userProfileArea').style.display='none';
  }
}

function openMyBookings(){
  const container = document.getElementById('bookingsListContainer');
  container.innerHTML = '';
  const myUserBookings = userBookings.filter(b => b.user === currentUser?.email);
  
  if(myUserBookings.length === 0){
    container.innerHTML = `<p style="text-align:center; color:var(--muted); padding:20px;">لا توجد حجوزات سابقة مسجلة حالياً.</p>`;
  } else {
    myUserBookings.forEach((b, index) => {
      const item = document.createElement('div');
      item.style.cssText = "background:#f7f5f0; border:1px solid var(--line); border-radius:10px; padding:12px; font-size:12px; display:flex; justify-content:space-between; align-items:center;";
      item.innerHTML = `<div><strong>حجز #${index+1}: ${b.dest}</strong><br><span style="color:var(--muted)">تاريخ السفر: ${b.date || 'غير محدد'}</span></div><div style="color:var(--teal); font-weight:bold;">${b.price.toLocaleString()} جنيه</div>`;
      container.appendChild(item);
    });
  }
  bookingsModal.classList.add('open');
}

function triggerCheckout(destName, basePrice){
  if(!currentUser){
    toast(translations[currentLang].requireLogin);
    openAuth('login');
    return;
  }
  const dateVal = document.getElementById('globalDateFilter').value || document.getElementById('travelDate').value;
  let multiplier = 1.0;
  if(dateVal){
    const d = new Date(dateVal);
    const month = d.getMonth() + 1;
    if([6, 7, 8, 12].includes(month)) multiplier = 1.25;
    else if([3, 4, 10, 11].includes(month)) multiplier = 1.10;
    else multiplier = 0.95;
  }
  const finalPrice = Math.round(basePrice * multiplier);
  currentBooking={dest: destName, price: finalPrice, date: dateVal, user: currentUser.email};

  document.getElementById('sumDestVal').textContent = destName + (dateVal ? ` (${dateVal})` : '');
  document.getElementById('sumPriceVal').textContent = finalPrice.toLocaleString() + ' جنيه (EGP)';
  checkoutModal.classList.add('open');
}

document.querySelectorAll('.book-dest-btn').forEach(btn=>{
  btn.addEventListener('click',()=>{
    triggerCheckout(btn.dataset.dest, parseFloat(btn.dataset.base));
  });
});

document.querySelectorAll('.book-pkg-btn').forEach(btn=>{
  btn.addEventListener('click',()=>{
    triggerCheckout(btn.dataset.pkg, parseFloat(btn.dataset.base));
  });
});

document.querySelectorAll('.book-hotel-btn').forEach(btn=>{
  btn.addEventListener('click',()=>{
    triggerCheckout(btn.dataset.hotel, parseFloat(btn.dataset.base));
  });
});

document.getElementById('paymentForm').addEventListener('submit',(e)=>{
  e.preventDefault();
  userBookings.push(currentBooking);
  localStorage.setItem('mm_user_bookings', JSON.stringify(userBookings));
  checkoutModal.classList.remove('open');
  toast(translations[currentLang].paymentSuccess);
});

document.getElementById('langToggle').addEventListener('click',()=>setLanguage(currentLang==='ar'?'en':'ar'));
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('mainNav').classList.toggle('open'));
document.querySelectorAll('#mainNav a').forEach(a=>a.addEventListener('click',()=>document.getElementById('mainNav').classList.remove('open')));

document.getElementById('searchForm').addEventListener('submit',e=>{
  e.preventDefault();
  const t=translations[currentLang],dest=document.getElementById('searchDest').value;
  if(!dest){toast(t.missingDestination);return;}
  let base = 15000;
  if(dest==='Maldives') base=58900;
  else if(dest==='Dubai') base=29900;
  else if(dest==='Cairo') base=8900;
  else if(dest==='Sharm El Sheikh') base=12900;
  else if(dest==='Dahab') base=7900;
  else if(dest==='Switzerland') base=79900;
  triggerCheckout(dest, base);
});

document.getElementById('contactForm').addEventListener('submit',e=>{
  e.preventDefault();
  const t=translations[currentLang],name=document.getElementById('name').value.trim(),email=document.getElementById('email').value.trim(),interest=document.getElementById('interest').selectedOptions[0].text,date=document.getElementById('date').value||'غير محدد',msg=document.getElementById('message').value.trim();
  const mailto=`mailto:${CONFIG.email}?subject=${encodeURIComponent('استفسار رحلة من: '+name)}&body=${encodeURIComponent('الاسم: '+name+'\nالبريد: '+email+'\nنوع الطلب: '+interest+'\nتاريخ السفر: '+date+'\n\nالتفاصيل:\n'+msg)}`;
  window.location.href=mailto;
});